import { mkdir, writeFile } from 'fs/promises';
import { dirname, resolve } from 'path';
import * as p from '@clack/prompts';
import { getReview, getWorkerUrl } from '../../lib/api.js';

export async function exportReviewCommand(
  reviewId: string,
  format: 'markdown' | 'json',
  outputPath: string
): Promise<void> {
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }
  if (!outputPath.trim()) {
    throw new Error('Output path is required');
  }

  const { review } = await getReview(workerUrl, reviewId);
  const absolutePath = resolve(outputPath);

  recommendation: ReviewRecommendation;
}

export interface ReviewFindingLocation {
  path: string;
  line: number;
}

export interface ReviewFinding {
  id: string;
  severity: ReviewSeverity;
  confidence: ReviewConfidence;
  title: string;
  description: string;
  conditions: string | null;
  locations: ReviewFindingLocation[];
  suggestedFix: {
    kind: 'text';
    value: string;
  } | null;

}

export interface ReviewContextRef {
  id: string;
  r2Key: string;
}

export interface ReviewIntentSummary {
  goal: string | null;
  constraints: string[];
  decisions: string[];
}

export interface ReviewProvenanceSummary {
  sessionIds: string[];
