            let reason = 'unknown';

            try {
              const latest = await github.rest.pulls.get({
                owner: context.repo.owner,
                repo: context.repo.repo,
                pull_number: pr.number,
              });

              const latestPr = latest.data;
              const latestHead = latestPr?.head?.sha;
              const latestBase = latestPr?.base?.sha;
              const authorLogin = latestPr?.user?.login;

              let hasWriteLikeAccess = false;
              if (authorLogin) {
                try {
                  const permission = await github.rest.repos.getCollaboratorPermissionLevel({
                    owner: context.repo.owner,
                    repo: context.repo.repo,
                    username: authorLogin,
                  });
                  const level = permission.data.permission;
